const app=document.getElementById('app');
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const qs=(s,r=document)=>r.querySelector(s),qsa=(s,r=document)=>[...r.querySelectorAll(s)];
function normalizeUiLanguage(v){return String(v||'').toLowerCase()==='en'?'en':'fr'}
function currentLanguage(){return normalizeUiLanguage(state.uiLanguage||state.settings?.language||state.status?.defaultLanguage||'fr')}
function currentLocale(){return currentLanguage()==='en'?'en-GB':'fr-FR'}
const fmtNumber=(n,d=1)=>new Intl.NumberFormat(currentLocale(),{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(n||0));
const fmtPct=n=>`${fmtNumber(n,1)} %`;
const fmtBytes=(n,d=1)=>{n=Number(n||0);if(!n)return currentLanguage()==='en'?'0 B':'0 o';const u=currentLanguage()==='en'?['B','KB','MB','GB','TB','PB']:['o','Ko','Mo','Go','To','Po'];const i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),u.length-1);return`${new Intl.NumberFormat(currentLocale(),{maximumFractionDigits:i>=3?d:0,minimumFractionDigits:0}).format(n/1024**i)} ${u[i]}`};
const fmtDate=s=>s?new Date(typeof s==='number'&&s<2e10?s*1000:s).toLocaleString(currentLocale()):'—';
const fmtUptime=s=>{s=Number(s||0);const d=Math.floor(s/86400),h=Math.floor((s%86400)/3600),m=Math.floor((s%3600)/60);return d?`${d}${currentLanguage()==='en'?'d':'j'} ${h}h`:`${h}h ${m}m`};
const fmtMoney=(v,c='EUR')=>new Intl.NumberFormat(currentLocale(),{style:'currency',currency:c||'EUR'}).format(Number(v||0));
const fmtTemp=n=>Number.isFinite(Number(n))?`${fmtNumber(n,1)} °C`:'—';
function tempKind(n){const v=Number(n),t=state.settings?.thresholds||{};if(!Number.isFinite(v))return'neutral';if(v>=Number(t.temperatureCritical||85))return'danger';if(v>=Number(t.temperatureWarning||75))return'warning';return'ok'}
function tempDiagTitle(n){return n?.temperatureDiagnosticTitle||(!Number.isFinite(Number(n?.temperatureC))?'Température indisponible':'Température disponible')}
function tempDiagDetail(n){return n?.temperatureDiagnosticDetail||n?.temperatureError||''}
function tempDiagAction(n){return n?.temperatureDiagnosticAction||''}
function tempDiagCode(n){return n?.temperatureDiagnosticCode||(!Number.isFinite(Number(n?.temperatureC))?'unknown':'ok')}
function tempUnavailableMarkup(n,{compact=false}={}){
  if(Number.isFinite(Number(n?.temperatureC)))return'';
  const title=tempDiagTitle(n),detail=tempDiagDetail(n),action=tempDiagAction(n),code=tempDiagCode(n);
  if(compact)return`<small class="temperature-reason" title="${esc([detail,action].filter(Boolean).join(' · '))}">${esc(title)}</small>`;
  return`<div class="temperature-reason-box"><div class="temperature-reason-head"><span>Diagnostic</span><code>${esc(code)}</code></div><strong>${esc(title)}</strong>${detail?`<p>${esc(detail)}</p>`:''}${action?`<div class="temperature-action">${esc(action)}</div>`:''}</div>`;
}

