function translateUiString(value){
  const raw=String(value??'');if(currentLanguage()!=='en'||!raw)return raw;
  const lead=raw.match(/^\s*/)?.[0]||'',trail=raw.match(/\s*$/)?.[0]||'',core=raw.slice(lead.length,raw.length-trail.length);
  if(!core)return raw;
  let out=EN_UI[core]||core;
  if(out===core){for(const [re,repl] of EN_RULES){if(re.test(core)){out=core.replace(re,repl);break}}}
  return lead+out+trail;
}
function applyRuntimeLanguage(root=document){
  document.documentElement.lang=currentLanguage();
  if(currentLanguage()!=='en')return;
  const skip='script,style,pre,code,textarea,[data-no-i18n]';
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  for(const node of nodes){const parent=node.parentElement;if(!parent||parent.closest(skip))continue;const next=translateUiString(node.nodeValue);if(next!==node.nodeValue)node.nodeValue=next}
  const attrs=['title','placeholder','aria-label'];for(const el of root.querySelectorAll?.('[title],[placeholder],[aria-label]')||[]){if(el.closest(skip))continue;for(const a of attrs){if(el.hasAttribute(a))el.setAttribute(a,translateUiString(el.getAttribute(a)))}}
}
function setUiLanguage(lang,{remember=true,render=true}={}){state.uiLanguage=normalizeUiLanguage(lang);if(remember)localStorage.setItem('proxpanel.uiLanguage',state.uiLanguage);document.documentElement.lang=state.uiLanguage;if(render){if(state.status?.authenticated)renderPage();else renderAuth(!state.status?.setupDone)}}


const apiInflight=new Map();
async function api(url,opt={}){
  const method=String(opt.method||'GET').toUpperCase(),dedupe=method==='GET'&&!opt.signal,key=dedupe?`${method}:${url}`:'';
  if(key&&apiInflight.has(key))return apiInflight.get(key);
  const started=performance.now();
  const run=(async()=>{
    const headers={...(opt.headers||{})};if(opt.body&&typeof opt.body==='string'&&!headers['Content-Type'])headers['Content-Type']='application/json';
    const r=await fetch(url,{credentials:'same-origin',...opt,headers});let b={};try{b=await r.json()}catch{}
    const elapsed=Math.round(performance.now()-started);
    state.perf.api.push({url:String(url).replace(/([?&](?:token|secret|password)=)[^&]+/gi,'$1***'),method,status:r.status,ms:elapsed,at:Date.now()});
    if(state.perf.api.length>80)state.perf.api.splice(0,state.perf.api.length-80);
    if(r.status===401&&state.status?.authenticated){state.status.authenticated=false;renderAuth(false);throw new Error('Session expirée.');}
    if(!r.ok)throw new Error(b.error||`HTTP ${r.status}`);return b;
  })();
  if(key){apiInflight.set(key,run);run.finally(()=>{if(apiInflight.get(key)===run)apiInflight.delete(key)}).catch(()=>{})}
  return run;
}
function resolvedUiTheme(prefs={}){
  const ui={...(state.settings?.ui||{}),...prefs},choice=ui.theme||'default',mode=ui.colorMode||'dark';
  if(choice==='light')return'light';
  if(mode==='light')return'light';
  if(mode==='auto'&&window.matchMedia?.('(prefers-color-scheme: light)')?.matches)return'light';
  return choice;
}
function applyUiPreferences(overrides={}){
  const ui={...(state.settings?.ui||{}),...overrides},root=document.documentElement;
  root.dataset.theme=resolvedUiTheme(ui);
  root.dataset.themeChoice=ui.theme||'default';
  root.dataset.density=ui.density||'comfortable';
  root.dataset.menuStyle=ui.menuStyle||'standard';
  root.dataset.motion=ui.reduceMotion?'reduced':'full';
  const customAccent=String(ui.accent||'').trim();
  if(customAccent)root.style.setProperty('--accent',customAccent);else root.style.removeProperty('--accent');
  const theme=root.dataset.theme;
  const themeColors={light:'#f4f7fb',default:'#080a0d',graphite:'#080d14',neon:'#030709',purple:'#0b0711',contrast:'#000000'};
  const barColor=themeColors[theme]||themeColors.default;
  let meta=qs('meta[name="theme-color"]');
  if(!meta){meta=document.createElement('meta');meta.name='theme-color';document.head.appendChild(meta)}
  meta.setAttribute('content',barColor);
  root.style.colorScheme=theme==='light'?'light':'dark';
}
function slowApiMetrics(){return [...(state.perf?.api||[])].sort((a,b)=>b.ms-a.ms).slice(0,8)}
function toast(msg,type='ok'){const n=document.createElement('div');n.className=`toast ${type}`;n.textContent=translateUiString(msg);document.body.appendChild(n);setTimeout(()=>n.remove(),4800)}
