function badge(text,kind='neutral'){return`<span class="pill ${kind}">${esc(translateUiString(text))}</span>`}
function field(label,id,value='',type='text',extra=''){return`<label class="field"><span>${esc(translateUiString(label))}</span><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,id,options,value=''){return`<label class="field"><span>${esc(translateUiString(label))}</span><select id="${id}">${options.map(o=>{const x=typeof o==='string'?{value:o,label:o}:o;return`<option value="${esc(x.value)}" ${String(x.value)===String(value)?'selected':''}>${esc(translateUiString(x.label))}</option>`}).join('')}</select></label>`}
function selectedServer(){return state.servers.find(s=>s.id===state.selectedServer)||null}
function d(){return state.dashboard||{metrics:{},history:{cpu:[],memory:[],storage:[],network:[]},health:{},nodes:[],machines:[],storages:[],tasks:[],backup:{jobs:[],unprotected:[],machines:[],inventory:[]},problems:[],capacity:{},energy:{nodes:[]}}}
