function wsUrl(path){const u=new URL(path,location.href);u.protocol=location.protocol==='https:'?'wss:':'ws:';return u.toString()}
function brandMarkSvg(){return`<svg class="brand-symbol" viewBox="0 0 48 48" aria-hidden="true"><path d="M8 14 24 5l16 9v20l-16 9-16-9z" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linejoin="round"/><path d="m14 19 10-6 10 6-10 6zM14 29l10 6 10-6" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`}

function smoothSvgPath(points,tension=1){
  if(!points?.length)return'';if(points.length===1)return`M ${points[0].x.toFixed(3)} ${points[0].y.toFixed(3)}`;
  let d=`M ${points[0].x.toFixed(3)} ${points[0].y.toFixed(3)}`;
  for(let i=0;i<points.length-1;i++){
    const p0=points[i-1]||points[i],p1=points[i],p2=points[i+1],p3=points[i+2]||p2;
    const k=Math.max(0,Math.min(1.25,Number(tension)||1))/6;
    const c1x=p1.x+(p2.x-p0.x)*k,c1y=p1.y+(p2.y-p0.y)*k;
    const c2x=p2.x-(p3.x-p1.x)*k,c2y=p2.y-(p3.y-p1.y)*k;
    d+=` C ${c1x.toFixed(3)} ${c1y.toFixed(3)}, ${c2x.toFixed(3)} ${c2y.toFixed(3)}, ${p2.x.toFixed(3)} ${p2.y.toFixed(3)}`;
  }
  return d;
}
function normalizedChartRows(series){
  const rows=(series||[]).map((x,i)=>({v:Number(x?.value??x),time:Number(x?.time),i})).filter(x=>Number.isFinite(x.v));
  if(rows.length<2)return rows;
  if(rows.every(x=>Number.isFinite(x.time)&&x.time>0)){
    rows.sort((a,b)=>a.time-b.time);
    const dedup=[];for(const row of rows){if(dedup.length&&dedup.at(-1).time===row.time)dedup[dedup.length-1]=row;else dedup.push(row)}
    return dedup;
  }
  return rows;
}
function chartCoords(rows,{top=10,bottom=42,fixedMin=null,fixedMax=null}={}){
  const nums=rows.map(x=>x.v),min=fixedMin==null?Math.min(...nums):Number(fixedMin),max=fixedMax==null?Math.max(...nums):Number(fixedMax),range=Math.max(.00001,max-min);
  const hasTime=rows.every(x=>Number.isFinite(x.time)&&x.time>0),t0=hasTime?rows[0].time:0,t1=hasTime?rows.at(-1).time:rows.length-1,span=Math.max(1,t1-t0);
  return rows.map((row,i)=>({x:hasTime?((row.time-t0)/span)*100:(i/(rows.length-1))*100,y:bottom-((row.v-min)/range)*(bottom-top),v:row.v,time:row.time}));
}
function closedAreaPath(coords,line,bottom){
  if(!coords.length)return'';const first=coords[0],last=coords.at(-1);return`M ${first.x.toFixed(3)} ${Number(bottom).toFixed(3)} L ${first.x.toFixed(3)} ${first.y.toFixed(3)} ${line.replace(/^M\s+[-0-9.]+\s+[-0-9.]+\s*/, '')} L ${last.x.toFixed(3)} ${Number(bottom).toFixed(3)} Z`;
}
function spark(series,color='var(--cyan)'){
  const rows=normalizedChartRows(series);if(rows.length<2)return'<div class="spark empty">Historique en collecte…</div>';
  const coords=chartCoords(rows,{top:10,bottom:42}),last=coords.at(-1),line=smoothSvgPath(coords,.72),area=closedAreaPath(coords,line,42);
  return`<svg class="spark-svg" viewBox="0 0 100 46" preserveAspectRatio="none" role="img" aria-label="Évolution de la métrique"><line x1="0" y1="42" x2="100" y2="42" class="spark-base"/><path class="spark-area" d="${area}" fill="${color}"/><path class="spark-line" d="${line}" fill="none" stroke="${color}" stroke-width="1.8" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/><circle class="spark-dot" cx="${last.x}" cy="${last.y}" r="1.8" fill="${color}"><title>Dernière valeur : ${last.v.toFixed(1)}</title></circle></svg>`;
}
