function firewallPage(){return requireData(()=>{const f=state.firewall;return`<div class="page-head"><div><h1>Pare-feu</h1><p>Règles cluster, nœud et VM/LXC.</p></div><div class="actions">${button('+ Règle','firewall-add','primary')}</div></div><div class="v1-toolbar"><select id="fwScope"><option value="cluster" ${f.scope==='cluster'?'selected':''}>Cluster</option><option value="node" ${f.scope==='node'?'selected':''}>Nœud</option><option value="machine" ${f.scope==='machine'?'selected':''}>VM/LXC</option></select><select id="fwNode">${d().nodes.map(n=>`<option ${n.node===f.node?'selected':''}>${esc(n.node)}</option>`).join('')}</select><select id="fwMachine"><option value="">Machine</option>${d().machines.map(m=>`<option value="${m.type}:${m.vmid}:${esc(m.node)}" ${String(m.vmid)===String(f.vmid)&&m.type===f.type?'selected':''}>${m.vmid} · ${esc(m.name)}</option>`).join('')}</select>${button('Charger','firewall-load','primary')}</div><section class="panel"><div class="table-scroll"><table class="machine-table"><thead><tr><th>#</th><th>Type</th><th>Action</th><th>Source</th><th>Destination</th><th>Proto/port</th><th>Commentaire</th><th>Actions</th></tr></thead><tbody>${state.firewallRules.map((r,i)=>`<tr><td>${r.pos??i}</td><td>${esc(r.type||'')}</td><td>${badge(r.action||'',r.action==='ACCEPT'?'ok':r.action==='DROP'||r.action==='REJECT'?'danger':'neutral')}</td><td>${esc(r.source||'—')}</td><td>${esc(r.dest||'—')}</td><td>${esc([r.proto,r.dport].filter(Boolean).join('/')||'—')}</td><td>${esc(r.comment||'')}</td><td><div class="row-actions">${button('Modifier',`firewall-edit:${r.pos??i}`,'tiny')}${button('Supprimer',`firewall-delete:${r.pos??i}`,'tiny danger')}</div></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty-inline">Charge les règles du scope sélectionné.</div></td></tr>'}</tbody></table></div></section>`})}

function problemsPage(){return requireData(()=>`<div class="page-head"><div><h1>Problèmes à corriger</h1><p>Alertes calculées à partir des données Proxmox et des seuils.</p></div></div><section class="panel">${problemList(d().problems||[])}</section>`)}
function dependenciesPage(){const g=state.dependencies;return requireData(()=>`<div class="page-head"><div><h1>Carte des dépendances</h1><p>Domaine → service → VM/LXC → nœud → stockage.</p></div><div>${button('+ Dépendance','add-dependency','primary')}</div></div>${g?.error?`<div class="warning-box">${esc(g.error)}</div>`:''}<section class="panel section-card"><div class="dep-edge-list">${(g?.edges||[]).map(e=>`<div><b>${esc(e.from)}</b><i>→ ${esc(e.label||'dépend de')} →</i><b>${esc(e.to)}</b></div>`).join('')||'<div class="empty-inline">Aucune dépendance détectée.</div>'}</div></section>`)}
function changesPage(){return`<div class="page-head"><div><h1>Centre de changements</h1><p>Aperçu avant application des modifications matérielles/configuration.</p></div><div>${button('+ Changement','new-change','primary')}</div></div><div class="cards-grid">${state.changes.map(c=>`<article class="panel section-card"><div class="resource-title"><strong>${esc(c.machineName)} · ${c.vmid}</strong>${badge(c.status,c.status==='applied'?'ok':c.status==='pending'?'warning':'neutral')}</div><div class="diff">${Object.keys(c.after||{}).map(k=>`<div><span>${esc(k)}</span><del>${esc(c.before?.[k]??'—')}</del><ins>${esc(c.after?.[k])}</ins></div>`).join('')}</div>${c.status==='pending'?`<div class="actions">${button('Appliquer',`change-apply:${c.id}`,'primary')}${button('Annuler',`change-cancel:${c.id}`,'danger')}</div>`:''}</article>`).join('')||'<div class="panel empty-inline">Aucun changement.</div>'}</div>`}
function maintenancePage(){return requireData(()=>{const p=state.maintenancePlan;return`<div class="page-head"><div><h1>Maintenance guidée</h1><p>Prévol, migration, paquets, shell et redémarrage.</p></div></div><div class="v1-toolbar"><select id="maintNode">${d().nodes.map(n=>`<option>${esc(n.node)}</option>`).join('')}</select>${button('Préparer le plan','maintenance-plan','primary')}</div>${p?`<section class="panel section-card"><h3>${esc(p.node)}</h3><div class="list">${p.steps.map((s,i)=>`<div class="list-row"><span>${i+1}</span><div><strong>${esc(s.label)}</strong></div></div>`).join('')}</div><div class="actions wrap">${button('Migrer les machines','maintenance-migrate','primary',p.canMigrate?'':'disabled')}${button('Vérifier les mises à jour','maintenance-updates')}${button('Ouvrir le shell','maintenance-shell')}${button('Redémarrer','maintenance-reboot','danger')}</div>${state.maintenanceUpdates?`<div class="code-log">${esc(state.maintenanceUpdates.map(u=>`${u.Package||u.package||''} ${u.Version||u.version||''}`).join('\n'))}</div>`:''}</section>`:''}`})}
function automationsPage(){return`<div class="page-head"><div><h1>Automatisations</h1><p>Scénarios ordonnés avec délais et planification.</p></div><div>${button('+ Scénario','new-automation','primary')}</div></div><div class="cards-grid">${state.automations.map(a=>`<article class="panel section-card"><div class="resource-title"><strong>${esc(a.name)}</strong>${a.scheduleTime?badge(a.scheduleTime,'ok'):badge('Manuel')}</div><p class="muted">${esc(a.description||'')}</p><div class="code-log">${esc((a.steps||[]).map(s=>s.type==='wait'?`wait ${s.seconds}s`:`${s.vmid}:${s.action}`).join('\n'))}</div><div class="actions">${button('Lancer',`automation-run:${a.id}`,'primary')}${button('Supprimer',`automation-delete:${a.id}`,'danger')}</div></article>`).join('')||'<div class="panel empty-inline">Aucun scénario.</div>'}</div>`}
function dockerPage(){
  const overview=state.dockerOverview;
  if(!hasPortainerIntegration())return`<div class="page-head"><div><h1>Docker</h1><p>Supervision Docker via Portainer, sans accès direct au socket Docker.</p></div></div><div class="empty-state panel docker-empty"><div class="empty-icon">◆</div><h2>Portainer n’est pas encore configuré</h2><p>Ajoute Portainer depuis Administration → Intégrations. Community Edition est la cible de test principale ; Business Edition reste compatible lorsque les mêmes API sont disponibles.</p>${button('Configurer Portainer','open-portainer-admin','primary')}</div>`;
  if(state.dockerError&&!overview)return`<div class="page-head"><div><h1>Docker</h1><p>Supervision Docker via Portainer.</p></div><div>${button('Réessayer','docker-refresh','primary')}</div></div><div class="warning-box"><strong>Portainer indisponible</strong><p>${esc(state.dockerError)}</p></div>`;
  if(!overview)return'<div class="panel loading">Chargement des environnements Docker…</div>';
  const s=overview.summary||{},portainers=overview.portainers||[];
  return`<div class="page-head"><div><h1>Docker</h1><p>Vue consolidée des environnements Docker découverts via Portainer.</p></div><div class="actions">${button('Actualiser','docker-refresh','primary')}${button('Gérer Portainer','open-portainer-admin','secondary')}</div></div>
  <div class="docker-summary">
    <div class="panel"><span>Portainer</span><strong>${s.portainers||0}</strong><small>instance(s) configurée(s)</small></div>
    <div class="panel"><span>Environnements</span><strong>${s.environments||0}</strong><small>${s.reachable||0} joignable(s)</small></div>
    <div class="panel"><span>Conteneurs</span><strong>${s.containers||0}</strong><small>${s.running||0} running · ${s.stopped||0} arrêté(s)</small></div>
    <div class="panel ${s.unhealthy?'docker-warning':''}"><span>Unhealthy</span><strong>${s.unhealthy||0}</strong><small>health Docker</small></div>
  </div>
  ${state.dockerError?`<div class="warning-box"><strong>Données partiellement disponibles</strong><p>${esc(state.dockerError)}</p></div>`:''}
  <div class="docker-portainer-list">${portainers.map(p=>`<section class="panel docker-portainer-card"><div class="panel-head"><div><h3>◆ ${esc(p.name)}</h3><p>${esc(p.url)}${p.version?` · Portainer ${esc(p.version)}`:''}${p.edition?` · ${esc(p.edition)}`:''}</p></div>${badge(p.status==='online'?'Connecté':'Erreur',p.status==='online'?'ok':'danger')}</div>
    ${p.error?`<div class="docker-source-error">${esc(p.error)}</div>`:''}
    <div class="docker-environment-grid">${(p.environments||[]).map(e=>`<article class="docker-environment ${e.reachable?'':'offline'}"><div class="docker-environment-head"><div><strong>${esc(e.name)}</strong><small>${esc(e.hostName||e.url||'Environnement Portainer')}</small></div>${badge(e.reachable?(e.supported?'Docker Standalone':e.kindLabel||'Docker'):'Inaccessible',e.reachable?(e.supported?'ok':'warning'):'danger')}</div>
      ${e.reachable?`<div class="docker-host-meta"><span>Docker <b>${esc(e.dockerVersion||'N/D')}</b></span><span>CPU <b>${e.cpus||'—'}</b></span><span>RAM <b>${e.memoryTotal?fmtBytes(e.memoryTotal):'—'}</b></span><span>OS <b>${esc(e.os||'—')}</b></span></div><div class="docker-container-stats"><div><span>Total</span><b>${e.containers?.total||0}</b></div><div><span>Running</span><b>${e.containers?.running||0}</b></div><div><span>Stopped</span><b>${e.containers?.stopped||0}</b></div><div class="${e.containers?.unhealthy?'bad':''}"><span>Unhealthy</span><b>${e.containers?.unhealthy||0}</b></div></div>${e.supported?'':'<div class="docker-beta-note">Découvert mais non géré dans beta.1. Docker Standalone est pris en charge en priorité.</div>'}`:`<div class="docker-source-error">${esc(e.error||'Environnement inaccessible.')}</div>`}
    </article>`).join('')||'<div class="empty-inline">Aucun environnement Portainer détecté.</div>'}</div></section>`).join('')}</div>`;
}
function integrationsPage(){return adminIntegrationsPage()}
function auditPage(){return`<div class="page-head"><div><h1>Journal d’audit</h1><p>Qui a lancé quelle action, quand et avec quel résultat.</p></div></div><section class="panel"><div class="audit-list">${state.audit.map(a=>`<div class="audit-row"><time>${fmtDate(a.at)}</time><div><strong>${esc(a.user)} · ${esc(a.action)}</strong><small>${esc(a.target||'')} ${a.ip?`· ${esc(a.ip)}`:''}</small></div>${badge(a.result||'ok',a.result==='ok'?'ok':'danger')}</div>`).join('')||'<div class="empty-inline">Journal vide.</div>'}</div></section>`}

const UPDATE_DAY_LABELS=[['D',0],['L',1],['Ma',2],['Me',3],['J',4],['V',5],['S',6]];
function updateWindowRow(win={},index=0){
  const days=Array.isArray(win.days)&&win.days.length?win.days.map(Number):[0,1,2,3,4,5,6],start=win.start||'02:00',end=win.end||'05:00';
  return`<div class="update-window-row update-window-card" data-update-window><div class="update-window-head"><div><span class="update-window-index">${index+1}</span><div><strong>Créneau ${index+1}</strong><small>Jours et plage de maintenance autorisés</small></div></div>${button('Supprimer','remove-update-window','tiny danger')}</div><div class="update-window-layout"><div class="update-window-days"><span>Jours</span><div class="update-days">${UPDATE_DAY_LABELS.map(([label,value])=>`<label title="${['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'][value]}"><input type="checkbox" data-window-day value="${value}" ${days.includes(value)?'checked':''}><span>${label}</span></label>`).join('')}</div></div><div class="update-window-times"><label class="field"><span>Début</span><input type="time" data-window-start value="${esc(start)}"></label><span class="update-window-arrow">→</span><label class="field"><span>Fin</span><input type="time" data-window-end value="${esc(end)}"></label></div></div></div>`;
}
function collectAutoInstallWindows(){return qsa('[data-update-window]').map((row,index)=>({id:`window-${index+1}`,days:qsa('[data-window-day]:checked',row).map(x=>Number(x.value)),start:qs('[data-window-start]',row)?.value||'02:00',end:qs('[data-window-end]',row)?.value||'05:00'}));}
function selectedOtaChannel(){return qs('input[name="otaChannel"]:checked')?.value||state.settings?.updates?.otaChannel||'stable';}

function updatePanel(){
  const u=state.updates, cfg=state.settings?.updates||{}, remote=state.remoteUpdate||{};if(!u)return'<div class="loading">Chargement…</div>';
  const officialUrl=remote.officialOtaBaseUrl||'https://updates.proxpanel.fr';
  const otaBase=cfg.otaBaseUrl||officialUrl,otaChannel=cfg.otaChannel||'stable',pinned=!!cfg.otaKeyPinned,fp=cfg.otaPublicKeyFingerprint||remote.otaFingerprint||'';
  const isOfficial=remote.officialOta!==false && otaBase.replace(/\/$/,'')===officialUrl.replace(/\/$/,'');
  const otaTest=state.otaTest||null;
  const latest=state.otaLatest||null;
  const autoWindows=Array.isArray(cfg.autoInstallWindows)&&cfg.autoInstallWindows.length?cfg.autoInstallWindows:[{days:[0,1,2,3,4,5,6],start:'02:00',end:'05:00'}];
  const autoInstallStatus=cfg.autoInstallEnabled===true?(remote.autoInstallWindowOpen?badge('Créneau ouvert','ok'):badge('En attente du créneau','warning')):badge('Désactivée','neutral');
  const installedType=String(remote.installedVersionType||(String(u.currentVersion||'').includes('-')?'beta':'stable')).toLowerCase();
  const installedTypeLabel=installedType==='stable'?'Stable':'Beta';
  const updateChannelLabel=otaChannel==='stable'?'Stable':'Beta';
  const latestAvailableVersion=remote.available?remote.version:(remote.latestVersion||'—');
  const latestReleaseCard=(rel,label,kind)=>{
    if(!rel)return`<article class="ota-latest-release empty"><div class="ota-latest-head"><strong>${label}</strong>${badge('Aucune release','neutral')}</div><p>Aucune version ${label.toLowerCase()} publiée ou visible pour cette instance.</p></article>`;
    const status=rel.sameAsInstalled?badge('Installée','ok'):rel.newerThanInstalled?badge('Plus récente','warning'):badge('Publiée','neutral');
    return`<article class="ota-latest-release ${kind}"><div class="ota-latest-head"><div><span class="ota-channel-label">${label}</span><strong>v${esc(rel.version)}</strong></div>${status}</div>${rel.title?`<h5>${esc(rel.title)}</h5>`:''}${rel.summaryFr?`<p>${esc(rel.summaryFr)}</p>`:''}<div class="ota-latest-meta"><span>📅 ${rel.publishedAt?fmtDate(rel.publishedAt):'Date non renseignée'}</span><span>🚀 Déploiement ${Number(rel.rollout??100)} %</span>${rel.mandatory?'<span>⚠️ Obligatoire</span>':''}${rel.signatureVerified?'<span>🔐 Manifeste vérifié</span>':''}</div>${(rel.improvements||[]).length?`<div class="ota-latest-list"><b>✨ Améliorations</b><ul>${rel.improvements.slice(0,6).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${(rel.fixes||[]).length?`<div class="ota-latest-list"><b>🛠️ Corrections</b><ul>${rel.fixes.slice(0,6).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${(rel.securityNotesFr||[]).length?`<div class="ota-latest-security"><b>🔐 Sécurité</b><ul>${rel.securityNotesFr.slice(0,5).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}</article>`;
  };
  const latestBlock=`<section class="ota-latest-block"><div class="panel-head no-pad"><div><h3>Dernières versions publiées</h3><p>Informations récupérées directement depuis <strong>updates.proxpanel.fr</strong>.</p></div>${button('Actualiser les infos','check-ota-latest','secondary')}</div>${latest?`<div class="ota-latest-grid">${latestReleaseCard(latest.beta,'BETA','beta')}${latestReleaseCard(latest.stable,'STABLE','stable')}</div><div class="ota-latest-footer"><span>Dernière lecture : ${fmtDate(latest.fetchedAt)}</span><span>${latest.summaryEndpointAvailable?'API publique /summary':'Compatibilité OTA /check'}</span></div>`:`<div class="ota-empty"><strong>Informations OTA non chargées</strong><small>Utilise « Actualiser les infos » pour interroger le serveur officiel.</small></div>`}</section>`;
  const releaseCard=remote.available?`<div class="ota-release ${remote.signatureVerified?'verified':'unverified'}"><div class="panel-head no-pad"><div><h4>${remote.securityNotesFr?.length?'⚠️':'🚀'} ProxPanel ${esc(remote.version)} disponible</h4><p>${esc(remote.summaryFr||remote.title||'Nouvelle version publiée sur le serveur OTA officiel.')}</p></div>${remote.signatureVerified?badge('Signature vérifiée','ok'):badge('Vérification en attente','warning')}</div><div class="metric-strip compact"><div><span>Type de version</span><strong>${esc(String(remote.availableVersionType||remote.releaseChannel||'—').toUpperCase())}</strong></div><div><span>Déploiement</span><strong>${Number(remote.rollout??100)} %</strong></div><div><span>Obligatoire</span><strong>${remote.mandatory?'OUI':'NON'}</strong></div><div><span>Taille</span><strong>${remote.fileSize?fmtBytes(remote.fileSize):'—'}</strong></div></div>${(remote.releaseNotesFr||[]).length?`<div class="release-notes"><strong>Améliorations / corrections</strong><ul>${remote.releaseNotesFr.slice(0,12).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${(remote.securityNotesFr||[]).length?`<div class="security-callout"><strong>🔐 Sécurité</strong><ul>${remote.securityNotesFr.slice(0,10).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<div class="actions wrap">${remote.signatureVerified?button('Installer depuis OTA','install-ota-update','primary'):button('Vérifier maintenant','check-updates','secondary')}</div></div>`:`<div class="ota-empty"><strong>${remote.configured?'✅ Aucune mise à jour OTA disponible':'Connexion OTA en attente'}</strong>${remote.lastCheckAt?`<small>Dernier contrôle : ${fmtDate(remote.lastCheckAt)}</small>`:''}${remote.error?`<small class="danger-text">${esc(remote.error)}</small>`:''}</div>`;
  return`<div class="update-panel beta-update" id="updateCenter"><div class="beta-warning"><strong>Canal OTA indépendant de la version installée</strong><p>Tu peux utiliser une version Beta tout en suivant le canal Stable, ou basculer une installation Stable vers le canal Beta. ProxPanel ne propose jamais une version plus ancienne que celle installée.</p></div><div class="update-current update-current-grid"><div><span>Version installée</span><strong>${esc(u.currentVersion)}</strong></div><div><span>Type de version installée</span><strong>${esc(installedTypeLabel)}</strong></div><div><span>Canal de mises à jour</span><strong>${esc(updateChannelLabel)}</strong></div><div><span>Dernière vérification</span><strong>${remote.lastCheckAt?esc(fmtDate(remote.lastCheckAt)):'—'}</strong></div><div><span>Dernière version disponible</span><strong>${esc(latestAvailableVersion)}</strong></div><div><span>Bootstrap</span><strong>${esc(u.bootstrapVersion)}</strong></div></div>
  <div class="zip-separator"><span>Serveur OTA officiel</span></div><div class="ota-settings"><div class="official-ota-card"><div><span class="official-ota-icon">☁</span><div><strong>updates.proxpanel.fr</strong><small>${esc(officialUrl)}</small></div></div>${badge(remote.error?'Connexion à vérifier':'OTA officiel','ok')}</div><input id="otaBaseUrl" type="hidden" value="${esc(isOfficial?officialUrl:otaBase)}"><div class="update-channel-card"><div><strong>Canal de mises à jour</strong><small>Le choix est enregistré immédiatement et persiste dans les données ProxPanel. Changer de canal relance automatiquement une vérification OTA.</small></div><div class="ota-channel-selector"><label class="ota-channel-option ${otaChannel==='stable'?'selected':''}"><input type="radio" name="otaChannel" value="stable" ${otaChannel==='stable'?'checked':''}><span><b>Stable</b><small>Versions recommandées pour une utilisation normale.</small></span></label><label class="ota-channel-option ${otaChannel==='beta'?'selected':''}"><input type="radio" name="otaChannel" value="beta" ${otaChannel==='beta'?'checked':''}><span><b>Beta</b><small>Accès anticipé aux nouvelles fonctionnalités.</small></span></label></div></div><label class="check"><input id="updateAutoEnabled" type="checkbox" ${cfg.autoCheckEnabled!==false?'checked':''}> Vérifier automatiquement les mises à jour ProxPanel</label><div class="two-col">${selectField('Fréquence','updateCheckHours',[{value:1,label:'Toutes les heures'},{value:3,label:'Toutes les 3 h'},{value:6,label:'Toutes les 6 h'},{value:12,label:'Toutes les 12 h'},{value:24,label:'Toutes les 24 h'}],cfg.checkIntervalHours||6)}<div class="update-notify-options"><label class="check"><input id="updateNotifyPanel" type="checkbox" ${cfg.notifyPanel!==false?'checked':''}> Panel</label><label class="check"><input id="updateNotifyDiscord" type="checkbox" ${cfg.notifyDiscord!==false?'checked':''}> Discord</label><label class="check"><input id="updateNotifyEmail" type="checkbox" ${cfg.notifyEmail!==false?'checked':''}> E-mail</label></div></div><div class="auto-install-config"><div class="auto-install-title"><div><strong>Installation automatique</strong><small>Installer les nouvelles versions OTA uniquement pendant les fenêtres de maintenance choisies.</small></div>${autoInstallStatus}</div><label class="check auto-install-toggle"><input id="updateAutoInstallEnabled" type="checkbox" ${cfg.autoInstallEnabled===true?'checked':''}> Installer automatiquement les mises à jour disponibles</label><div class="update-window-list" id="updateMaintenanceWindows">${autoWindows.map((w,i)=>updateWindowRow(w,i)).join('')}</div><div class="actions wrap">${button('+ Ajouter un créneau','add-update-window','secondary')}</div><p class="muted">Fuseau horaire : <strong>${esc(state.settings?.timezone||remote.autoInstallTimeZone||'UTC')}</strong>. Une mise à jour automatique reste soumise aux contrôles de signature Ed25519, SHA-256 et version minimale. ProxPanel redémarre automatiquement après l’installation.</p>${remote.autoInstallLastAt?`<p class="muted">Dernière installation automatique : ${fmtDate(remote.autoInstallLastAt)}${remote.autoInstallLastVersion?` · v${esc(remote.autoInstallLastVersion)}`:''}</p>`:''}${remote.autoInstallLastError?`<div class="warning-box"><strong>Dernière tentative automatique</strong><p>${esc(remote.autoInstallLastError)}</p></div>`:''}</div><div class="ota-identity"><div><span>Instance anonyme</span><code>${esc(cfg.otaInstanceId||remote.instanceId||'—')}</code></div><div><span>Signature OTA</span><strong>${pinned?'🔒 Clé mémorisée':'🔐 Initialisation automatique'}</strong>${fp?`<code>${esc(fp)}</code>`:''}</div></div>${otaTest?`<div class="${otaTest.ok?'success-box':'warning-box'}"><strong>${otaTest.ok?'✅ Serveur OTA officiel joignable':'⚠️ Test OTA'}</strong><p>${otaTest.available?`Mise à jour ${esc(otaTest.release?.version||'')} disponible.`:'Aucune mise à jour disponible.'}</p></div>`:''}<div class="actions wrap">${button('Enregistrer','save-update-check','primary')}${button('Tester la connexion','test-ota-server','secondary')}${button('Vérifier maintenant','check-updates','secondary')}</div><p class="muted">Aucune configuration OTA n’est nécessaire pour une installation publique. ProxPanel utilise automatiquement <strong>https://updates.proxpanel.fr</strong> en HTTPS et mémorise la clé de signature officielle lors de la première connexion valide.</p><details class="ota-dev"><summary>Mode développeur · serveur OTA personnalisé</summary><p class="muted">Réservé aux environnements de test. Un serveur personnalisé nécessite un épinglage manuel de sa clé Ed25519.</p>${field('URL OTA personnalisée','otaCustomBaseUrl',isOfficial?'':otaBase,'url','placeholder="https://ota-dev.example.net"')}<div class="actions wrap">${button('Utiliser ce serveur','save-custom-ota','secondary')}${!isOfficial?button('Épingler sa clé','trust-ota-key','secondary'):''}${!isOfficial?button('Revenir au serveur officiel','restore-official-ota','secondary'):''}</div></details></div>${latestBlock}${releaseCard}
  <details class="zip-fallback"><summary>Mise à jour manuelle par ZIP (secours)</summary><p class="muted">Cette méthode reste disponible si le serveur OTA officiel est indisponible.</p><label class="zip-drop"><input id="updateZip" type="file" accept=".zip,application/zip"><span>Choisir proxpanel-update-vX.X.X-beta.X.zip</span></label><div class="actions">${button('Installer le ZIP','install-update','primary')}${u.rollbackAvailable?button(`Rollback ${esc(u.rollbackVersion)}`,'rollback','danger'):''}</div></details><div class="update-history">${(u.history||[]).slice(0,8).map(h=>`<div><strong>${esc(h.action)} · ${esc(h.fromVersion||'')} → ${esc(h.toVersion||'')}</strong><small>${fmtDate(h.at)}</small></div>`).join('')}</div></div>`
}
function pveUpdatesPage(){
  const p=state.pveUpdates||{},cfg=state.settings?.pveUpdates||{},servers=p.servers||[];
  const rows=servers.map(srv=>`<section class="panel section-card"><div class="panel-head no-pad"><div><h3>${esc(srv.serverName||'Proxmox')}</h3><p>${srv.error?esc(srv.error):`${(srv.nodes||[]).reduce((n,x)=>n+Number(x.count||0),0)} paquet(s) à mettre à jour`}</p></div></div>${(srv.nodes||[]).map(n=>`<details class="mail-smtp-fallback" ${n.count?'open':''}><summary><strong>${esc(n.node)}</strong> · ${n.error?`Erreur : ${esc(n.error)}`:`${n.count} mise(s) à jour · ${n.criticalCount||0} critique(s) · ${n.securityCount||0} sécurité`}</summary>${n.error?'':`<div class="list">${(n.updates||[]).map(u=>`<div class="list-row pve-update-row ${u.level||'standard'}"><div><strong>${esc(u.package)} ${badge((u.level||'standard').toUpperCase(),u.level==='critical'?'danger':u.level==='security'?'warning':'neutral')}</strong><small>${esc(u.categoryFr||'')} · ${esc(u.oldVersion||'—')} → ${esc(u.version||'—')}</small>${(u.cves||[]).length?`<div class="cve-line">CVE : ${u.cves.map(c=>`<code>${esc(c)}</code>`).join(' ')}</div>`:''}${(u.highlightsFr||[]).length?`<ul class="muted">${u.highlightsFr.map(h=>`<li>${esc(h)}</li>`).join('')}</ul>`:''}</div>${button('Changelog',`pve-changelog:${encodeURIComponent(n.node)}:${encodeURIComponent(u.package)}:${encodeURIComponent(u.version||'')}`,'tiny')}</div>`).join('')||'<div class="empty-inline">Aucune mise à jour disponible.</div>'}</div>`}</details>`).join('')||'<div class="empty-inline">Aucun nœud disponible.</div>'}</section>`).join('')||'<div class="panel empty-inline">Aucun résultat. Lance une vérification.</div>';
  return`<div class="page-head"><div><h1>Mises à jour Proxmox VE</h1><p>Contrôle APT de tous les nœuds, détection CVE/sécurité et rapports Panel, Discord et e-mail.</p></div><div>${button('Vérifier maintenant + rapport','check-pve-updates','primary')}</div></div><section class="panel section-card"><div class="panel-head no-pad"><div><h3>Contrôle automatique</h3><p>Le worker vérifie les nœuds même quand le navigateur est fermé.</p></div></div><label class="check"><input id="pveUpdateEnabled" type="checkbox" ${cfg.enabled!==false?'checked':''}> Activer le contrôle automatique</label><div class="two-col">${selectField('Fréquence','pveUpdateHours',[{value:1,label:'Toutes les heures'},{value:3,label:'Toutes les 3 h'},{value:6,label:'Toutes les 6 h'},{value:12,label:'Toutes les 12 h'},{value:24,label:'Toutes les 24 h'}],cfg.checkIntervalHours||6)}<div class="update-notify-options"><label class="check"><input id="pveNotifyPanel" type="checkbox" ${cfg.notifyPanel!==false?'checked':''}> Panel</label><label class="check"><input id="pveNotifyDiscord" type="checkbox" ${cfg.notifyDiscord!==false?'checked':''}> Discord auto</label><label class="check"><input id="pveNotifyEmail" type="checkbox" ${cfg.notifyEmail!==false?'checked':''}> E-mail auto</label></div></div><label class="check"><input id="pveRefreshApt" type="checkbox" ${cfg.refreshApt!==false?'checked':''}> Rafraîchir APT avant le contrôle</label><label class="check"><input id="pveIncludeChangelog" type="checkbox" ${cfg.includeChangelog!==false?'checked':''}> Récupérer les changelogs, CVE et résumé français</label><div class="manual-report-box"><strong>Contrôle manuel</strong><label class="check"><input id="pveManualEmail" type="checkbox" ${cfg.manualReportEmail!==false?'checked':''}> Toujours envoyer un rapport e-mail, même si aucun paquet n’est disponible</label><label class="check"><input id="pveManualDiscord" type="checkbox" ${cfg.manualReportDiscord!==false?'checked':''}> Envoyer aussi le rapport manuel sur Discord</label><label class="check"><input id="pveManualAudit" type="checkbox" ${cfg.manualAudit!==false?'checked':''}> Journaliser le contrôle manuel</label></div><div class="actions wrap">${button('Enregistrer','save-pve-update-check','primary')}</div>${p.lastCheckAt?`<p class="muted">Dernier contrôle : ${fmtDate(p.lastCheckAt)}${p.nextCheckAt?` · prochain : ${fmtDate(p.nextCheckAt)}`:''}</p>`:''}<div class="metric-strip"><div><span>Paquets</span><strong>${Number(p.totalUpdates||0)}</strong></div><div class="critical-metric"><span>Critiques</span><strong>${Number(p.criticalTotal||0)}</strong></div><div><span>Sécurité</span><strong>${Number(p.securityTotal||0)}</strong></div><div><span>Nœuds</span><strong>${Number(p.totalNodes||0)}</strong></div></div>${(p.cves||[]).length?`<div class="security-callout"><strong>Références CVE détectées</strong><p>${p.cves.map(c=>`<code>${esc(c)}</code>`).join(' ')}</p><small>La criticité affichée est déterminée à partir des changelogs disponibles. Vérifie le changelog officiel avant intervention.</small></div>`:''}</section>${rows}`
}
const DISCORD_EVENT_OPTIONS=[
  ['backup.success','Sauvegarde réussie'],['backup.failed','Sauvegarde échouée'],['backup.stale','Sauvegarde en retard / manquée'],['backup.unprotected','Machine non protégée'],
  ['node.offline','Nœud hors ligne'],['node.recovered','Nœud rétabli'],['task.failed','Tâche échouée'],['storage.warning','Stockage warning'],['storage.critical','Stockage critique'],
  ['resources.cpu','CPU élevée'],['resources.memory','RAM élevée'],['pve.update.available','Mises à jour Proxmox disponibles'],['pve.update.security','Mises à jour sécurité / CVE'],['pve.update.manual-report','Rapport manuel PVE']
];
function discordChannelsAdmin(a){const rows=a.discordChannels||[];return`<div class="discord-admin"><div class="discord-intro"><div><strong>Routage Discord par salon</strong><small>Chaque webhook peut recevoir uniquement les événements que tu choisis.</small></div>${button('+ Ajouter un salon','add-discord-channel','primary')}</div><div class="discord-channel-list">${rows.map(ch=>`<div class="discord-channel"><div class="discord-channel-main"><div class="discord-channel-title"><strong># ${esc(ch.name)}</strong>${badge(ch.enabled?'Actif':'Désactivé',ch.enabled?'ok':'neutral')}</div><small>${(ch.events||[]).map(e=>DISCORD_EVENT_OPTIONS.find(x=>x[0]===e)?.[1]||e).join(' · ')||'Aucun événement'}</small></div><div class="row-actions">${button('Tester',`test-discord-channel:${ch.id}`,'tiny')}${button('Configurer',`edit-discord-channel:${ch.id}`,'tiny')}${button('Supprimer',`delete-discord-channel:${ch.id}`,'tiny danger')}</div></div>`).join('')||'<div class="empty-inline">Aucun salon Discord configuré.</div>'}</div></div>`}
function openDiscordChannel(id=''){const ch=(state.settings?.alerts?.discordChannels||[]).find(x=>x.id===id)||{name:'',events:['backup.failed','backup.stale','node.offline','task.failed','pve.update.available'],enabled:true};modal(id?'Configurer le salon Discord':'Ajouter un salon Discord',`${field('Nom du salon','discordName',ch.name||'')}${field(id?'Nouveau webhook (laisser vide pour conserver)':'Webhook Discord','discordWebhook','')}<label class="check"><input id="discordEnabled" type="checkbox" ${ch.enabled!==false?'checked':''}> Activer ce salon</label><div class="discord-event-grid">${DISCORD_EVENT_OPTIONS.map(([value,label])=>`<label class="check"><input type="checkbox" data-discord-event="${value}" ${(ch.events||[]).includes(value)?'checked':''}> ${label}</label>`).join('')}</div><p class="muted">Exemple : tu peux envoyer uniquement les sauvegardes vers #backups, les nœuds vers #infra et les alertes ressources vers #monitoring.</p>`,`<button class="btn secondary" data-action="close-modal">Annuler</button><button class="btn primary" data-action="save-discord-channel:${id||'new'}">Enregistrer</button>`) }

async function openDashboardGroups(){
  state.dashboardGroups=await api('/api/dashboard-groups');
  const body=`<div class="dashboard-group-list">${state.dashboardGroups.map(g=>`<div class="list-row"><div><strong>${esc(g.name)}</strong><small>${(g.members||[]).reduce((n,m)=>n+(m.nodes?.length||1),0)} source(s) · ${(g.members||[]).map(m=>state.servers.find(s=>s.id===m.serverId)?.name||m.serverId).join(', ')}</small></div><div class="row-actions">${button('Supprimer',`delete-dashboard-group:${g.id}`,'tiny danger')}</div></div>`).join('')||'<div class="empty-inline">Aucune vue multi-nœuds.</div>'}</div><p class="muted">Une vue peut regrouper des nœuds provenant de plusieurs serveurs ou clusters Proxmox indépendants.</p>`;
  modal('Vues du dashboard',body,`<button class="btn secondary" data-action="close-modal">Fermer</button><button class="btn primary" data-action="new-dashboard-group">+ Nouvelle vue</button>`)
}
async function openDashboardGroupForm(){
  state.dashboardGroupCandidates=await api('/api/dashboard-groups/candidates');
  const sources=state.dashboardGroupCandidates.map(srv=>`<div class="dashboard-source"><strong>${esc(srv.serverName)}</strong>${srv.error?`<small class="danger-text">${esc(srv.error)}</small>`:''}<div class="dashboard-node-checks">${(srv.nodes||[]).length?(srv.nodes||[]).map(n=>`<label class="check"><input type="checkbox" data-dg-source data-server="${esc(srv.serverId)}" data-node="${esc(n)}"> ${esc(n)}</label>`).join(''):`<label class="check"><input type="checkbox" data-dg-source data-server="${esc(srv.serverId)}" data-node=""> Tout le serveur/cluster</label>`}</div></div>`).join('');
  modal('Nouvelle vue multi-nœuds',`${field('Nom de la vue','dashboardGroupName','','text','placeholder="Ex. Production"') }<div class="dashboard-source-list">${sources||'<div class="empty-inline">Aucun serveur disponible.</div>'}</div>`,`<button class="btn secondary" data-action="manage-dashboard-groups">Retour</button><button class="btn primary" data-action="save-dashboard-group">Créer la vue</button>`)
}


