  ['Système','system.test','Test système','Validation générale du canal e-mail.','info'],
  ['Nœuds','node.offline','Nœud hors ligne','Alerte critique lorsqu’un nœud ne répond plus.','critical'],
  ['Nœuds','node.recovered','Nœud rétabli','Confirmation lorsqu’un nœud répond de nouveau.','info'],
  ['Nœuds','temperature.warning','Température élevée','Température CPU au-dessus du seuil warning.','warning'],
  ['Nœuds','temperature.critical','Température critique','Température CPU au-dessus du seuil critique.','critical'],
  ['Sauvegardes','backup.success','Sauvegarde réussie','Confirmation d’un backup terminé correctement.','info'],
  ['Sauvegardes','backup.failed','Sauvegarde échouée','Échec d’un job de sauvegarde.','critical'],
  ['Sauvegardes','backup.stale','Sauvegarde en retard','Dernier backup plus ancien que le seuil autorisé.','warning'],
  ['Sauvegardes','backup.unprotected','Machine non protégée','VM/LXC sans sauvegarde récente détectée.','warning'],
  ['Infrastructure','task.failed','Tâche échouée','Erreur sur une tâche Proxmox.','critical'],
  ['Infrastructure','storage.warning','Stockage en alerte','Stockage au-dessus du seuil warning.','warning'],
  ['Infrastructure','storage.critical','Stockage critique','Stockage au-dessus du seuil critique.','critical'],
  ['Ressources','resources.cpu','CPU élevée','Charge CPU supérieure au seuil configuré.','warning'],
  ['Ressources','resources.memory','RAM élevée','Mémoire utilisée supérieure au seuil configuré.','warning'],
  ['Mises à jour','system.update.available','Mise à jour ProxPanel','Nouvelle version ProxPanel disponible.','info'],
  ['Mises à jour','pve.update.available','Mises à jour Proxmox','Nouveaux paquets PVE disponibles.','info'],
  ['Mises à jour','pve.update.security','Sécurité Proxmox','Correctifs de sécurité PVE disponibles.','critical'],
  ['Mises à jour','pve.update.manual-report','Rapport PVE manuel','Rapport manuel des mises à jour PVE.','info'],
  ['Sécurité','auth.2fa.email','Code de secours 2FA','Modèle envoyé pour le secours 2FA par e-mail.','warning']
