function mailTestPanel(a={}){
  const groups=[...new Set(MAIL_TEST_CATALOG.map(x=>x[0]))];
  const recipient=String(a.smtp?.to||'').split(/[;,]/)[0]?.trim()||'';
  return`<section class="panel notification-center-section mail-lab"><div class="panel-head"><div><h3>🧪 Laboratoire e-mail</h3><p>Aperçois et envoie chaque modèle d’alerte individuellement avec des données de démonstration.</p></div>${badge(`${MAIL_TEST_CATALOG.length} modèles`,'neutral')}</div><div class="notification-body"><div class="mail-lab-toolbar"><label class="field"><span>Destinataire de test</span><input id="mailTestRecipient" type="email" value="${esc(recipient)}" placeholder="test@domaine.fr"></label><div class="mail-brand-note"><div class="mail-brand-mini">${brandMarkSvg()}</div><div><strong>Nouvelle identité e-mail ProxPanel</strong><small>Logo officiel · graphite · orange ProxPanel · structure responsive</small></div></div></div>${groups.map(group=>`<div class="mail-test-group"><div class="mail-test-group-head"><strong>${esc(group)}</strong><span>${MAIL_TEST_CATALOG.filter(x=>x[0]===group).length} modèle(s)</span></div><div class="mail-test-grid">${MAIL_TEST_CATALOG.filter(x=>x[0]===group).map(([,type,label,desc,sev])=>`<article class="mail-test-card ${sev}"><div class="mail-test-card-top"><span class="mail-test-icon">${sev==='critical'?'!':sev==='warning'?'!':'✓'}</span><div><strong>${esc(label)}</strong><small>${esc(desc)}</small></div></div><div class="row-actions">${button('Aperçu',`preview-mail-template:${type}`,'tiny')}${button('Envoyer',`test-mail-template:${type}`,'tiny primary')}</div></article>`).join('')}</div></div>`).join('')}</div></section>`;
}

function notificationsPage(){
  const a=state.settings?.alerts||{},problems=d().problems||[];
  return`<div class="page-head"><div><h1>Notifications</h1><p>Centre unique des alertes Panel, Discord et e-mail.</p></div><div class="actions">${button('Tester tous les canaux','test-alerts','secondary')}${button('Notifications navigateur','enable-notifications','secondary')}</div></div>
  <div class="notification-summary"><div class="panel notification-stat"><span>Alertes actives</span><strong>${problems.length}</strong><small>${problems.filter(x=>x.severity==='critical').length} critique(s)</small></div><div class="panel notification-stat"><span>Discord</span><strong>${(a.discordChannels||[]).filter(x=>x.enabled!==false).length}</strong><small>salon(s) actif(s)</small></div><div class="panel notification-stat"><span>E-mail</span><strong>${a.smtp?.enabled?'ACTIF':'OFF'}</strong><small>${esc(a.smtp?.mode==='m365-graph'?'Microsoft 365 Graph':a.smtp?.mode==='smtp'?'SMTP / STARTTLS':'Non configuré')}</small></div></div>
  <section class="panel notification-center-section"><div class="panel-head"><div><h3>🔔 Alertes du panel</h3><p>Les alertes calculées à partir de ton infrastructure sont regroupées ici.</p></div>${button('Voir les détails','go-problems','tiny')}</div>${problemList(problems)}</section>
  <section class="panel notification-center-section"><div class="panel-head"><div><h3>💬 Discord</h3><p>Messages structurés, emojis, priorité, cible, détails et action recommandée.</p></div></div><div class="notification-body">${discordChannelsAdmin(a)}</div></section>
  <section class="panel notification-center-section mail-config-pro"><div class="panel-head"><div><h3>✉️ E-mail</h3><p>Modèles HTML ProxPanel avec logo officiel et identité visuelle homogène.</p></div>${button('Envoyer un test général','test-mail','tiny')}</div><div class="notification-body"><div class="mail-brand-preview"><div class="mail-brand-preview-logo">${brandMarkSvg()}</div><div><span>PROXPANEL</span><strong>Notifications professionnelles</strong><small>En-tête graphite, accent orange, criticité lisible, détails structurés et action recommandée.</small></div></div><label class="check"><input id="smtpEnabled" type="checkbox" ${a.smtp?.enabled?'checked':''}> Activer les notifications e-mail</label>${selectField('Mode d’envoi','mailMode',[{value:'m365-graph',label:'Microsoft 365 · OAuth / Graph (recommandé)'},{value:'smtp',label:'SMTP / STARTTLS'}],a.smtp?.mode||'m365-graph')}<div class="mail-box"><strong>Microsoft 365 · OAuth</strong><small>Application Entra avec permission Application Mail.Send et consentement administrateur.</small><div class="two-col">${field('Tenant ID','mailTenant',a.smtp?.tenantId||'')}${field('Client ID','mailClientId',a.smtp?.clientId||'')}</div>${field('Client secret','mailClientSecret','','password',a.smtp?.hasClientSecret?'placeholder="Secret déjà enregistré — laisser vide pour conserver"':'')}${field('Boîte expéditrice','mailSender',a.smtp?.sender||a.smtp?.from||'','email','placeholder="notifications@domaine.fr"')}</div><details class="mail-smtp-fallback"><summary>Paramètres SMTP / STARTTLS</summary><div class="two-col">${field('Hôte','smtpHost',a.smtp?.host||'smtp.office365.com')}${field('Port','smtpPort',a.smtp?.port||587,'number')}</div>${selectField('Sécurité','smtpSecurity',[{value:'starttls',label:'STARTTLS'},{value:'tls',label:'TLS direct'},{value:'none',label:'Aucune'}],a.smtp?.security||'starttls')}${field('Utilisateur','smtpUser',a.smtp?.username||'')}${field('Mot de passe','smtpPass','','password',a.smtp?.hasPassword?'placeholder="Mot de passe déjà enregistré — laisser vide pour conserver"':'')}</details><div class="two-col">${field('Adresse De','smtpFrom',a.smtp?.from||a.smtp?.sender||'','email')}${field('Destinataire(s)','smtpTo',a.smtp?.to||'','text','placeholder="admin@domaine.fr; autre@domaine.fr"')}</div><div class="actions wrap">${button('Enregistrer l’e-mail','save-alerts','primary')}</div></div></section>
  ${mailTestPanel(a)}`
}

const PANEL_PERMISSION_OPTIONS=[
  ['dashboard.view','Voir le dashboard'],['machines.view','Voir les machines'],['machines.control','Contrôler VM/LXC'],['console.use','Ouvrir les consoles'],['backups.run','Lancer des backups'],['tasks.manage','Gérer les tâches'],['pve.updates','Contrôler les mises à jour PVE'],['audit.view','Voir l’audit'],['admin.manage','Administrer ProxPanel'],['admin.users','Gérer les utilisateurs']
];
function roleLabel(role){return({admin:'Administrateur',operator:'Opérateur',viewer:'Lecture seule',custom:'Personnalisé'})[role]||role}
function usersPage(){
  const rows=state.users||[];
  return`<div class="page-head"><div><h1>Utilisateurs</h1><p>Comptes ProxPanel, adresse e-mail de secours, rôles et double authentification.</p></div><div>${button('+ Ajouter un utilisateur','add-panel-user','primary')}</div></div><section class="panel users-panel"><div class="user-list">${rows.map(u=>`<div class="panel-user-row"><div class="panel-user-avatar">${esc((u.displayName||u.username||'?').slice(0,1).toUpperCase())}</div><div class="panel-user-copy"><strong>${esc(u.displayName||u.username)}</strong><small>@${esc(u.username)} · ${esc(u.email||'⚠ e-mail à renseigner')} · ${esc(roleLabel(u.role))}${u.totpEnabled?` · 🔐 2FA active · ${u.recoveryCodesRemaining||0} secours`:''}${u.lastLoginAt?` · dernière connexion ${fmtDate(u.lastLoginAt)}`:''}</small></div><div class="panel-user-state">${badge(u.active===false?'Désactivé':'Actif',u.active===false?'neutral':'ok')}</div><div class="row-actions">${button('Modifier',`edit-panel-user:${u.id}`,'tiny')}${u.totpEnabled?button('Désactiver 2FA',`disable-user-totp:${u.id}`,'tiny danger'):button('Configurer 2FA',`setup-user-totp:${u.id}`,'tiny')}${u.totpEnabled&&u.id===state.me?.id?button('Nouveaux codes',`regenerate-recovery:${u.id}`,'tiny'):''}${u.id!==state.me?.id?button('Supprimer',`delete-panel-user:${u.id}`,'tiny danger'):''}</div></div>`).join('')||'<div class="empty-inline">Aucun utilisateur.</div>'}</div></section><div class="security-note panel"><strong>🔐 Sécurité de connexion</strong><p>La 2FA utilise une application Authenticator par QR Code. En cas de téléphone perdu ou HS : codes de récupération à usage unique, puis code temporaire envoyé à l’adresse e-mail du compte via la configuration mail ProxPanel.</p></div>`
}
function openPanelUser(id=''){
  const u=(state.users||[]).find(x=>x.id===id)||{username:'',displayName:'',email:'',role:'viewer',permissions:[],active:true};
  const custom=u.role==='custom';
  modal(id?'Modifier l’utilisateur':'Ajouter un utilisateur',`${field('Nom affiché','panelUserDisplay',u.displayName||'')}${field('Identifiant','panelUserName',u.username||'')}${field('Adresse e-mail','panelUserEmail',u.email||'','email','required autocomplete="email" placeholder="utilisateur@domaine.fr"')}<small class="muted">Obligatoire. Cette adresse sert notamment au secours 2FA si le téléphone est perdu, cassé ou inaccessible.</small>${field(id?'Nouveau mot de passe (laisser vide pour conserver)':'Mot de passe','panelUserPassword','','password','minlength="12" autocomplete="new-password"')}<small class="muted">12 caractères minimum.</small>${selectField('Rôle','panelUserRole',[{value:'admin',label:'Administrateur — accès complet'},{value:'operator',label:'Opérateur — exploitation et consoles'},{value:'viewer',label:'Lecture seule'},{value:'custom',label:'Personnalisé'}],u.role||'viewer')}<label class="check"><input id="panelUserActive" type="checkbox" ${u.active!==false?'checked':''}> Compte actif</label><div id="customPermissions" class="permission-grid" ${custom?'':'hidden'}>${PANEL_PERMISSION_OPTIONS.map(([v,l])=>`<label class="check"><input type="checkbox" data-panel-permission="${v}" ${(u.permissions||[]).includes(v)?'checked':''}> ${l}</label>`).join('')}</div>`,`<button class="btn secondary" data-action="close-modal">Annuler</button><button class="btn primary" data-action="save-panel-user:${id||'new'}">Enregistrer</button>`)
}
async function openTotpSetup(userId){const r=await api(`/api/users/${userId}/totp-setup`,{method:'POST',body:'{}'});modal('Configurer la double authentification',`<div class="totp-setup"><div class="security-callout"><strong>🔐 Double authentification ProxPanel</strong><p>Scanne le QR Code avec Microsoft Authenticator, Google Authenticator, 1Password, Bitwarden ou toute application TOTP compatible.</p></div><div class="totp-qr">${r.qrSvg||''}</div><label class="field"><span>Clé manuelle</span><input value="${esc(r.secret)}" readonly></label><div class="recovery-info"><strong>✉️ Secours si ton téléphone est perdu ou HS</strong><p>Un code temporaire pourra être envoyé à <b>${esc(r.emailMasked||'ton adresse e-mail')}</b> en réutilisant la configuration e-mail de ProxPanel.</p>${r.emailRecoveryAvailable?'<span class="status-pill ok">E-mail de secours disponible</span>':'<span class="status-pill warning">Configuration e-mail ProxPanel à activer pour utiliser ce secours</span>'}</div><div class="recovery-info"><strong>🧾 Codes de récupération</strong><p>Après validation, 10 codes à usage unique seront générés. Enregistre-les dans un endroit sûr : ils ne seront affichés qu’une fois.</p></div>${field('Code à 6 chiffres','totpEnableCode','','text','inputmode="numeric" autocomplete="one-time-code" maxlength="6"')}</div>`,`<button class="btn secondary" data-action="close-modal">Annuler</button><button class="btn primary" data-action="confirm-user-totp:${userId}">Activer la 2FA</button>`)}
function showRecoveryCodes(codes,title='Codes de récupération'){const list=(codes||[]).map(c=>`<code>${esc(c)}</code>`).join('');modal(title,`<div class="recovery-codes"><div class="warning-box"><strong>⚠️ Enregistre ces codes maintenant</strong><p>Chaque code est utilisable une seule fois et ne sera plus affiché après fermeture de cette fenêtre.</p></div><div class="recovery-code-grid">${list}</div></div>`,`<button class="btn secondary" data-action="copy-recovery-codes" data-codes="${esc((codes||[]).join('\n'))}">Copier</button><button class="btn secondary" data-action="download-recovery-codes" data-codes="${esc((codes||[]).join('\n'))}">Télécharger .txt</button><button class="btn primary" data-action="close-modal">J’ai enregistré mes codes</button>`)}

