function adminAdvancedPage(){
  const s=state.settings||{},moduleKeys=['overview','machines','nodes','monitoring','storage','docker','backups','tasks','templates','problems','dependencies','changes','maintenance','pveupdates','automations','audit','notifications','users','admin'],order=s.menuOrder||moduleKeys;
  return`${adminBack('Avancé','Navigation, modules et comportement temps réel.')}<div class="admin8-advanced-grid"><section class="panel admin8-card admin8-modules"><div class="admin8-card-head"><div><span class="admin8-title-icon">▦</span><div><h3>Navigation et modules</h3><p>Active uniquement les rubriques utiles. L’ordre actuel reste mémorisé.</p></div></div></div><input id="setMenuOrder" type="hidden" value="${esc(order.join(','))}"><div class="admin8-module-grid">${order.map(k=>`<label class="admin8-module"><input type="checkbox" data-module="${k}" ${s.modules?.[k]!==false?'checked':''}><span><b>${tr(k)}</b><small>${k}</small></span></label>`).join('')}</div><div class="admin-savebar">${button('Enregistrer les modules','save-general','primary')}</div></section><section class="panel admin8-card admin8-refresh-card"><div class="admin8-card-head"><div><span class="admin8-title-icon">↻</span><div><h3>Temps réel du dashboard</h3><p>Choisis le compromis entre réactivité et charge API.</p></div></div></div><div class="admin8-refresh-control"><div><span>Intervalle</span><strong><input id="setDashboardRefreshSeconds" type="number" min="5" max="300" step="1" value="${Number(s.ui?.dashboardRefreshSeconds||10)}"> <b>secondes</b></strong><small>Minimum 5 s · maximum 300 s.</small></div><div class="admin8-refresh-scale"><span>Réactif</span><i></i><span>Économe</span></div></div><div class="admin-savebar">${button('Appliquer','save-dashboard-refresh','primary')}</div></section></div>`;
}
function adminPage(){
  const section=state.adminSection||'home';
  let content;
  if(section==='general')content=adminGeneralPage();
  else if(section==='servers')content=adminServersPage();
  else if(section==='interface')content=adminInterfacePage();
  else if(section==='monitoring')content=adminMonitoringPage();
  else if(section==='integrations')content=adminIntegrationsPage();
  else if(section==='notifications')content=notificationsPage();
  else if(section==='security')content=usersPage();
  else if(section==='updates')content=adminUpdatesPage();
  else if(section==='application')content=adminApplicationPage();
  else if(section==='advanced')content=adminAdvancedPage();
  else content=adminHomePage();
  return adminFrame(content);
}

function renderPage(){if(state.tvMode){app.innerHTML=tvModePage();applyRuntimeLanguage(app);return}const pages={overview:overviewPage,machines:machinesPage,nodes:nodesPage,monitoring:monitoringPage,storage:storagePage,docker:dockerPage,backups:backupsPage,tasks:tasksPage,templates:templatesPage,problems:problemsPage,dependencies:dependenciesPage,changes:changesPage,maintenance:maintenancePage,pveupdates:pveUpdatesPage,automations:automationsPage,audit:auditPage,notifications:notificationsPage,users:usersPage,admin:adminPage};app.innerHTML=shell((pages[state.currentPage]||overviewPage)());bindDrag();applyRuntimeLanguage(app);}

function openProblemDetail(id){
  const p=(d().problems||[]).find(x=>x.id===id);if(!p)return toast('Alerte introuvable.','error');
  const sev=p.severity==='critical'?'Critique':'Avertissement';
  const facts=(p.facts||[]).map(f=>`<div class="problem-fact"><span>${esc(f.label)}</span><strong>${esc(f.value)}</strong></div>`).join('');
  const items=(p.items||[]).map(i=>`<div class="problem-item"><div><strong>${esc(i.label)}</strong><small>${esc(i.meta||'')}</small></div>${i.upid?button('Voir le log',`task-log:${encodeURIComponent(i.upid)}`,'tiny'):''}</div>`).join('');
  const routeLabels={tasks:'Tâches',backups:'Sauvegardes',monitoring:'Monitoring',storage:'Stockage',nodes:'Nœuds'};
  const body=`<div class="problem-detail-head"><span class="severity ${p.severity}">${p.severity==='critical'?'!':'△'}</span><div><div class="pill ${p.severity==='critical'?'danger':'warning'}">${sev}</div><p>${esc(p.detail)}</p></div></div>${facts?`<div class="problem-facts">${facts}</div>`:''}${items?`<div class="problem-items"><h3>Détails détectés</h3>${items}</div>`:''}<div class="problem-recommendation"><strong>Action recommandée</strong><p>${esc(p.recommendation||'Consulte la page correspondante pour analyser le détail avant toute action.')}</p></div>`;
  const footer=`<button class="btn secondary" data-action="close-modal">Fermer</button>${p.route?`<button class="btn primary" data-action="problem-route:${esc(p.route)}">Ouvrir ${esc(routeLabels[p.route]||p.route)}</button>`:''}`;
  modal(p.title,body,footer);
}
function modal(title,body,footer='',extraClass=''){let root=qs('#modalRoot');if(root)root.remove();root=document.createElement('div');root.id='modalRoot';root.className='modal-backdrop';root.innerHTML=`<div class="modal-card ${esc(extraClass)}" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close-modal" aria-label="Fermer">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</div>`;document.body.appendChild(root);applyRuntimeLanguage(root);return root}
function closeModal(){const r=qs('#modalRoot');if(r){if(r._term){clearInterval(r._term.keep);r._term.ro?.disconnect();r._term.ws?.close();r._term.term?.dispose()}if(r._rfb)try{r._rfb.disconnect()}catch{}r.remove()}}

function openAddServer(first=false){modal(first?'Ajouter votre premier serveur Proxmox':'Ajouter un serveur Proxmox',`${first?'<div class="onboarding-note"><strong>Bienvenue dans ProxPanel</strong><p>Votre compte administrateur est créé. Ajoutez maintenant un serveur ou cluster Proxmox VE. Aucune donnée de démonstration n’est préchargée.</p></div>':''}${field('Nom','srvName','','text','placeholder="Ex. Cluster principal"')}${field('URL','srvUrl','','url','placeholder="https://192.168.1.10:8006"')}${field('Utilisateur complet','srvUser','','text','placeholder="root@pam ou utilisateur@realm"')}<label class="field"><span>Authentification</span><select id="srvMode"><option value="interactive">Utilisateur + mot de passe à chaque session (non stocké)</option><option value="password">Mot de passe chiffré persistant</option><option value="token">API Token</option></select></label>${field('Mot de passe','srvPassword','','password')}${field('Token ID','srvTokenId','')}${field('Token secret','srvTokenSecret','','password')}<label class="check"><input id="srvSelf" type="checkbox" checked> Autoriser certificat auto-signé + certificate pinning</label>${field('Empreinte SHA-256 optionnelle','srvFingerprint','')}${field('MAC Wake-on-LAN','srvMac','')}`,`<button class="btn secondary" data-action="close-modal">Annuler</button><button class="btn primary" data-action="save-server">Ajouter</button>`)}
function openPveLogin(serverId=state.selectedServer){const s=state.servers.find(v=>v.id===serverId);if(!s)return toast('Serveur introuvable.','error');modal(`Connexion Proxmox · ${esc(s.name)}`,`${field('Utilisateur / realm','pveUser',s.username||'root@pam')}${field('Mot de passe','pvePassword','','password')}<div id="otpSlot"></div><p class="muted">Le mot de passe de cette connexion interactive n’est pas stocké. Si Proxmox demande la 2FA, le champ TOTP apparaîtra.</p>`,`<button class="btn secondary" data-action="close-modal">Annuler</button><button class="btn primary" data-action="submit-pve-login" data-server="${s.id}">Connexion</button>`)}
function resolveMachineTarget(serverId,type,vmid,node=''){
  const candidates=(d().machines||[]).filter(x=>x.type===type&&Number(x.vmid)===Number(vmid));
  if(serverId){const exact=candidates.find(x=>String(x.serverId||state.selectedServer||'')===String(serverId));if(exact)return exact}
  if(node){const exact=candidates.find(x=>String(x.node||'')===String(node));if(exact)return exact}
  return candidates[0]||null;
}
function openMachineMenu(serverId,type,vmid,node=''){const m=resolveMachineTarget(serverId,type,vmid,node);if(!m)return toast('Machine introuvable dans la vue courante.','error');const sid=m.serverId||serverId||state.selectedServer,host=m.node||node,acts=['start','shutdown','reboot','stop','suspend','resume',...(type==='qemu'?['hibernate','reset']:[])];modal(`${esc(m.name)} · ${vmid}`,`<div class="machine-menu"><div class="machine-menu-status">${badge(m.status,m.status==='running'?'ok':'neutral')} <span>${esc(host)}</span>${m.serverName?`<span>· ${esc(m.serverName)}</span>`:''}</div><div class="action-grid">${acts.map(a=>button(a,`machine-action:${sid}:${type}:${vmid}:${a}`,'secondary')).join('')}</div><div class="actions wrap">${button('Détails',`machine-details:${sid}:${type}:${vmid}:${encodeURIComponent(host)}`,'primary')}${button('Console',`console:${sid}:${type}:${vmid}:${host}`)}${type==='qemu'?button('Console série',`console:${sid}:qemu:${vmid}:${host}:term`):''}${type==='qemu'?button('SPICE',`spice:${sid}:${vmid}`):''}</div></div>`)}

async function openMachineDetail(serverId,type,vmid,node=''){
  const known=resolveMachineTarget(serverId,type,vmid,node),sid=known?.serverId||serverId||state.selectedServer,nodeHint=known?.node||node||'';
  const root=modal(`Machine ${vmid}`,'<div class="loading">Chargement des détails…</div>','', 'machine-detail-modal');
  try{
    const info=await api(`/api/servers/${encodeURIComponent(sid)}/machines/${type}/${vmid}/detail${nodeHint?`?node=${encodeURIComponent(nodeHint)}`:''}`);if(!document.body.contains(root))return;
    const m=info.machine,c=info.config||{},os=info.guestAgent?.osinfo||{},snaps=info.snapshots||[],serverName=info.serverName||known?.serverName||state.servers.find(s=>s.id===sid)?.name||'Proxmox';
    const ips=(info.ips||[]).filter(ip=>!['127.0.0.1','::1'].includes(String(ip)));
    qs('.modal-head h2',root).textContent=`${m.name} · ${m.vmid}`;
    qs('.modal-body',root).innerHTML=`<div class="machine-detail-hero"><div class="machine-detail-ident"><span class="machine-detail-icon ${type}">◇</span><div><h3>${esc(m.name)}</h3><p>${type==='qemu'?'VM QEMU':'Conteneur LXC'} · VMID ${m.vmid} · ${esc(serverName)} / ${esc(m.node)}</p></div></div><div class="machine-detail-state">${badge(m.status==='running'?'En ligne':m.status,m.status==='running'?'ok':'neutral')}</div></div>
      <div class="machine-detail-metrics"><div><span>CPU</span><strong>${fmtPct(m.cpu)}</strong></div><div><span>Mémoire</span><strong>${fmtBytes(m.mem)} <small>/ ${fmtBytes(m.maxmem)}</small></strong></div><div><span>Disque</span><strong>${diskDisplay(m)}</strong><small>${esc(diskSourceLabel(m))}</small></div><div><span>Uptime</span><strong>${fmtUptime(m.uptime)}</strong></div></div>
      <div class="machine-detail-actions">${button('Ouvrir la console',`console:${sid}:${type}:${vmid}:${m.node}`,'primary')}${type==='qemu'?button('Console série',`console:${sid}:qemu:${vmid}:${m.node}:term`):''}${type==='qemu'?button('SPICE',`spice:${sid}:${vmid}`):''}${button('Modifier le hardware',`open-change:${sid}:${type}:${vmid}`)}</div>
      <div class="machine-detail-columns"><section class="panel machine-detail-section"><div class="machine-detail-section-head"><h3>Informations</h3><span>${esc(serverName)}</span></div><div class="machine-info-grid"><div><span>VMID</span><b>${m.vmid}</b></div><div><span>Nœud</span><b>${esc(m.node)}</b></div><div><span>Hostname</span><b>${esc(info.guestAgent?.hostname||c.hostname||c.name||'—')}</b></div><div><span>OS détecté</span><b>${esc(os['pretty-name']||os.name||c.ostype||'—')}</b></div><div class="wide"><span>Adresse(s) IP</span><b class="ip-list">${ips.length?ips.map(ip=>`<code>${esc(ip)}</code>`).join(' '):'—'}</b></div><div class="wide"><span>Tags</span><b>${esc(c.tags||m.tags||'—')}</b></div></div></section>
      <section class="panel machine-detail-section"><div class="machine-detail-section-head"><h3>Opérations</h3><span>Actions courantes</span></div><div class="machine-operation-grid">${button('Backup',`backup-run:${sid}:${type}:${vmid}:${m.node}`,'primary')}${button('Cloner',`clone:${sid}:${type}:${vmid}`)}${button('Migrer',`migrate:${sid}:${type}:${vmid}`)}${button('Actions d’alimentation',`machine-menu:${sid}:${type}:${vmid}:${encodeURIComponent(m.node)}`)}</div></section></div>
            ${type==='qemu'?`<section class="panel machine-detail-section guest-storage-panel beta2-guest-storage"><div class="machine-detail-section-head"><div><h3>Stockage invité</h3><span>${esc(info.storageInfo?.storageState?.label||diskSourceLabel(m))}</span></div>${badge(info.storageInfo?.storageState?.label||'État inconnu',info.storageInfo?.storageState?.tone||'neutral')}</div><div class="guest-storage-summary"><div><span>Capacité Proxmox</span><strong>${info.storageInfo?.configuredCapacity?fmtBytes(info.storageInfo.configuredCapacity):fmtBytes(m.maxdisk)}</strong><small>${info.storageInfo?.configuredDisks?.length||0} disque(s) virtuel(s)</small></div><div><span>Utilisé invité</span><strong>${info.storageInfo?.usedKnown?fmtBytes(info.storageInfo.used):'N/D'}</strong><small>${info.storageInfo?.source==='guest-agent'?'QEMU Guest Agent':'Occupation non confirmée'}</small></div><div><span>Libre invité</span><strong>${info.storageInfo?.free!=null?fmtBytes(info.storageInfo.free):'N/D'}</strong><small>${info.storageInfo?.usagePct!=null?`${fmtPct(info.storageInfo.usagePct)} utilisé`:'Donnée indisponible'}</small></div></div>${(info.storageInfo?.configuredDisks||[]).length?`<div class="configured-disk-list"><h4>Disques configurés dans Proxmox</h4>${info.storageInfo.configuredDisks.map(disk=>`<div class="configured-disk-row"><div><strong>${esc(disk.key)}</strong><small>${esc(disk.storage||'')} · ${esc(disk.volume||'')}</small></div><b>${disk.total?fmtBytes(disk.total):'Taille N/D'}</b></div>`).join('')}</div>`:''}${(info.storageInfo?.filesystems||[]).length?`<div class="guest-fs-grid">${info.storageInfo.filesystems.map(fs=>`<div class="guest-fs-item"><div><strong>${esc(fs.mountpoint||'Volume')}</strong><small>${esc(fs.type||'')}${fs.name?` · ${esc(fs.name)}`:''}</small></div><div>${fs.sizeKnown&&fs.total?`<b>${fmtBytes(fs.used)} utilisés</b><small>${fmtBytes(fs.free)} libres · ${fmtBytes(fs.total)} total · ${fmtPct(fs.usagePct)} utilisé</small>`:'<b>Occupation N/D</b><small>Guest Agent détecté, compteurs non fournis</small>'}</div></div>`).join('')}</div>`:`<div class="guest-storage-hint"><strong>${esc(info.storageInfo?.storageState?.label||'Occupation invitée indisponible')}</strong><p>${esc(info.storageInfo?.agentError||'La capacité virtuelle reste disponible, mais ProxPanel ne peut pas confirmer l’espace réellement utilisé dans Windows/Linux.')}</p></div>`}${info.storageInfo?.agentError&&(info.storageInfo?.filesystems||[]).length?`<div class="guest-storage-hint compact"><p>${esc(info.storageInfo?.agentError)}</p></div>`:''}</section>`:''}
      <section class="panel machine-detail-section machine-snapshots"><div class="machine-detail-section-head"><div><h3>Snapshots</h3><span>${snaps.filter(s=>s.name!=='current').length} snapshot(s)</span></div>${button('+ Nouveau snapshot',`snapshot-create:${sid}:${type}:${vmid}`,'primary')}</div><div class="snapshot-grid">${snaps.filter(s=>s.name!=='current').map(s=>`<article class="snapshot-item"><div><strong>${esc(s.name)}</strong><small>${esc(s.description||'Sans description')}</small></div><div class="row-actions">${button('Rollback',`snapshot-rollback:${sid}:${type}:${vmid}:${encodeURIComponent(s.name)}`,'tiny')}${button('Supprimer',`snapshot-delete:${sid}:${type}:${vmid}:${encodeURIComponent(s.name)}`,'tiny danger')}</div></article>`).join('')||'<div class="empty-inline">Aucun snapshot pour cette machine.</div>'}</div></section>
      <details class="panel raw-config-panel"><summary>Configuration avancée / brute <span>Afficher le JSON Proxmox</span></summary><div class="code-log">${esc(JSON.stringify(c,null,2))}</div></details>`;
  }catch(e){qs('.modal-body',root).innerHTML=`<div class="machine-detail-error"><strong>Impossible de charger cette machine</strong><p>${esc(e.message)}</p><p>Source demandée : ${esc(state.servers.find(s=>s.id===sid)?.name||sid)}${nodeHint?` · ${esc(nodeHint)}`:''}</p></div>`}
}

async function contentOptions(content){const out=[];for(const s of d().storages.filter(x=>String(x.content||'').includes(content)).slice(0,20)){try{const rows=await api(`/api/servers/${state.selectedServer}/storage/${encodeURIComponent(s.node)}/${encodeURIComponent(s.storage)}/content?content=${encodeURIComponent(content)}`);for(const r of rows)out.push({value:r.volid,label:`${r.volid} · ${fmtBytes(r.size)}`})}catch{}}return out}
async function openCreate(type){const nodes=d().nodes.map(n=>n.node),diskStores=[...new Set(d().storages.filter(s=>String(s.content||'').match(/images|rootdir/)).map(s=>s.storage))];if(type==='qemu'){toast('Chargement des ISO…');const isos=await contentOptions('iso');modal('Créer une VM QEMU',`${selectField('Nœud','newNode',nodes)}${field('VMID (vide = auto)','newVmid','','number')}${field('Nom','newName','nouvelle-vm')}<div class="two-col">${field('Cœurs','newCores',2,'number')}${field('RAM MiB','newMemory',4096,'number')}${selectField('Storage disque','newStorage',diskStores)}${field('Disque GiB','newDisk',32,'number')}</div>${selectField('ISO','newIso',[{value:'',label:'Aucun'},...isos])}${field('Bridge','newBridge','vmbr0')}${field('VLAN (optionnel)','newVlan','','number')}${selectField('OS type','newOstype',['l26','win10','win11','other'])}<label class="check"><input id="newAgent" type="checkbox" checked> QEMU Guest Agent</label><label class="check"><input id="newOnboot" type="checkbox"> Démarrer au boot</label>`,`<button class="btn secondary" data-action="close-modal">Annuler</button><button class="btn primary" data-action="create-qemu">Créer</button>`)}else{toast('Chargement des templates LXC…');const tpls=await contentOptions('vztmpl');modal('Créer un conteneur LXC',`${selectField('Nœud','newNode',nodes)}${field('VMID (vide = auto)','newVmid','','number')}${field('Hostname','newHostname','nouveau-lxc')}${selectField('Template','newTemplate',[{value:'',label:'Choisir…'},...tpls])}<div class="two-col">${field('Cœurs','newCores',2,'number')}${field('RAM MiB','newMemory',2048,'number')}${field('Swap MiB','newSwap',512,'number')}${selectField('Storage rootfs','newStorage',diskStores)}${field('Disque GiB','newDisk',8,'number')}${field('Bridge','newBridge','vmbr0')}</div>${field('IP','newIp','dhcp')}${field('VLAN','newVlan','','number')}${field('Mot de passe root (optionnel)','newPassword','','password')}<label class="check"><input id="newUnpriv" type="checkbox" checked> Conteneur non privilégié</label><label class="check"><input id="newOnboot" type="checkbox"> Démarrer au boot</label>`,`<button class="btn secondary" data-action="close-modal">Annuler</button><button class="btn primary" data-action="create-lxc">Créer</button>`)}}

