document.addEventListener('keydown',e=>{
  const tag=String(e.target?.tagName||'').toLowerCase(),typing=['input','textarea','select'].includes(tag)||e.target?.isContentEditable;
  if(e.key==='Escape'&&state.tvMode&&!document.fullscreenElement){state.tvMode=false;localStorage.removeItem('proxpanel.tvMode');renderPage();return}
  if(e.key==='Escape'&&qs('#modalRoot .modal')){closeModal();return}
  if(!typing&&e.key==='/'){e.preventDefault();qs('#globalSearch')?.focus();return}
  if(!typing&&String(e.key).toLowerCase()==='g'){state.shortcutPrefix='g';setTimeout(()=>{if(state.shortcutPrefix==='g')state.shortcutPrefix=''},900);return}
  if(!typing&&state.shortcutPrefix==='g'){
    const key=String(e.key).toLowerCase(),routes={m:'machines',n:'nodes',o:'overview',s:'storage'};
    if(routes[key]){state.shortcutPrefix='';state.currentPage=routes[key];renderPage();reloadSection().then(()=>{if(state.currentPage===routes[key])renderPage()});e.preventDefault()}
  }
});
